        let shared = &*self.shared;
        let buffer = &shared.buffer;
        let mask = shared.mask;
        let mask_u64 = mask as u64;
        let buffer_len = buffer.len();
        let buf_u64 = buffer_len as u64;
        let next = self.next;

        let idx = if mask == 0 {
            0usize
        } else if next < mask_u64 {
            next as usize
        } else if next == mask_u64 {
            mask
        } else {
            (next & mask_u64) as usize
