        let mut slot = buffer[idx].read().unwrap();
        let slot_pos = slot.pos;

        if slot_pos != next {
            let next_pos = if buffer_len == 1 {
                slot_pos.wrapping_add(1)
            } else {
                slot_pos.wrapping_add(buf_u64)
