    drop(rx);

    let mut got_closed = false;
    loop {
        match rx_clone.recv().await {
            Ok(msg) => println!("{}", msg),
            Err(RecvError::Closed) => { got_closed = true; break; }
            Err(RecvError::Lagged(n)) => println!("Lagged by {n}"),
        }
    }
